const researchSpecs = [
 {slug:'outsourced-helpdesk-ticket-categorization-drift-study',title:'Ticket Categorization Drift Across Outsourced Help Desk Shifts',excerpt:'A reproducible study of whether different shifts classify the same support evidence consistently enough for routing, reporting, and customer promises.',stats:[{value:'12',label:'paired classification fields'},{value:'8',label:'adverse case families'}],question:'Do provider shifts and client reviewers assign the same category, impact, request family, protected boundary, and destination when they receive the same frozen ticket evidence?',unit:'one de-identified ticket packet independently classified by at least two reviewers before they see the original disposition',domain:[`Build the sample from ordinary and difficult records: incomplete subject lines, mixed billing and access concerns, product defects described as account failure, duplicate-looking tickets with different tenants, multilingual wording, reopened work, and cases corrected after intake. Freeze customer wording, channel metadata, permitted account context, attachments by reference, product state, and the taxonomy version. Do not include the original tags or resolver group in the first review because those fields anchor later reviewers to the historical answer.`, `Use a field-level agreement matrix instead of one overall score. Compare request family, affected service, impact, urgency, security or privacy signal, identity state, customer goal, frontline permission, escalation owner, waiting reason, closure state, and reporting category. A pair can agree on the broad category yet disagree on the protected boundary that determines safe action. Report raw agreement and disagreement counts; if a chance-adjusted statistic is used, publish its assumptions and category prevalence.`, `Investigate drift by mechanism. Similar category names, hidden queue-specific meanings, examples copied from one product, missing “unknown” values, automation suggestions, shift coaching, and performance targets can all push reviewers toward different labels. The repair may be taxonomy consolidation, field help, a decision example, a separated risk flag, or removal of a metric that rewards convenient categorization. Do not solve every disagreement by telling agents to try harder.`],extra:[source('NIST AI Risk Management Framework','https://www.nist.gov/itl/ai-risk-management-framework','Risk-management context for automation-assisted classification.'),source('NIST AI RMF Playbook','https://airc.nist.gov/airmf-resources/playbook/','Suggested actions for governing and measuring AI-supported decisions.'),source('Federal Plain Language Guidelines','https://www.plainlanguage.gov/guidelines/','Guidance used to assess understandable category labels and instructions.'),source('GAO Assessing Data Reliability','https://www.gao.gov/products/gao-20-283g','Methodological context for completeness, accuracy, and reliability review.')],related:['helpdesk-qa-sampling-research','helpdesk-queue-routing-research','helpdesk-ticket-evidence-research']},
 {slug:'outsourced-helpdesk-callback-number-provenance-study',title:'Customer Callback Number Provenance in Outsourced Support',excerpt:'A source-bounded study of how support teams choose a callback number without trusting spoofed messages, stale profiles, or unverified ticket text.',stats:[{value:'9',label:'number provenance states'},{value:'7',label:'callback challenge cases'}],question:'What evidence is sufficient to choose a customer callback route when ticket text, caller ID, account profile, prior notes, and approved directories disagree?',unit:'one requested or attempted callback from intake through number selection, identity boundary, customer contact, accepted handoff, and outcome',domain:[`Define nine provenance states: verified profile number, customer-entered number through an authenticated session, contract directory, authorized case contact, prior approved callback, unverified ticket text, forwarded message, caller-ID observation, and number supplied by a third party. These states are not interchangeable. Caller ID can be spoofed, a profile can be stale, and an authenticated user may still request contact outside the approved lane. Preserve who supplied the number, through which channel, when, for what purpose, and which owner approved use.`, `Challenge the callback path with number-porting history, recycled numbers, shared family or business lines, extensions, international formatting, voice-over-IP routing, relay services, inaccessible voice-only instructions, urgent payment claims, and a caller asking the agent to ignore the ticket record. The specialist should never reveal protected account facts merely to test whether the person on the line recognizes them. Use the organization’s approved identity flow and an independently sourced route for suspected fraud.`, `Measure attempts only after provenance classification. Report calls placed, connections, failed routes, identity stops, alternate accessible channels, customer confirmations, suspected spoofing escalations, and corrections to authoritative records. A connected call is not a verified identity event; a missed call is not proof that the number is wrong. The desired endpoint is a support conversation reached through an approved, proportionate route with its evidentiary limit visible.`],extra:[source('FCC Caller ID Spoofing','https://www.fcc.gov/spoofing','Official consumer and enforcement context for falsified caller identification.'),source('FTC Phone Scams','https://consumer.ftc.gov/articles/phone-scams','Consumer-protection context for impersonation and callback caution.'),source('CISA Avoiding Social Engineering and Phishing Attacks','https://www.cisa.gov/news-events/news/avoiding-social-engineering-and-phishing-attacks','Authoritative social-engineering resistance guidance.'),source('NIST Digital Identity Guidelines','https://pages.nist.gov/800-63-4/','Identity proofing and authentication context for protected support actions.')],related:['helpdesk-customer-identity-verification-research','outsourced-helpdesk-social-engineering-resistance-study','helpdesk-call-triage-research']},
 {slug:'outsourced-helpdesk-portal-upload-link-expiry-study',title:'Portal Upload Link Expiry Reliability for Help Desk Evidence',excerpt:'A controlled study of whether secure upload links expire, reject reuse, preserve accessibility, and leave enough evidence for customer recovery.',stats:[{value:'10',label:'upload lifecycle events'},{value:'9',label:'expiry and recovery tests'}],question:'Can a buyer prove that a customer evidence-upload link is scoped, usable, time-bounded, non-reusable after expiry, and recoverable without moving sensitive files into ordinary email?',unit:'one generated upload invitation followed through delivery, access, authentication if required, file validation, receipt, expiry, retry, revocation, and final retention state',domain:[`Trace ten lifecycle events separately: request authorization, link generation, delivery, first access, identity or possession check, file selection, transfer completion, malware or policy validation, case attachment, and expiry or revocation. The customer-facing success screen, storage event, and ticket attachment can disagree. Preserve a correlation identifier without placing the secret URL, access token, or file content in the study sheet. Define whether opening, beginning an upload, or successful receipt consumes a single-use invitation.`, `Exercise links before, at, and after the declared deadline; across timezone and clock boundaries; after a case transfer; after password change; with an interrupted upload; with an unsupported format; with an oversized file; from keyboard and assistive technology; and after manual revocation. Confirm that an expired link does not reveal the file name, case, customer, or storage location. The recovery path should issue a fresh invitation only after the approved requester and purpose are rechecked.`, `Report usable-delivery rate, successful receipt, false expiry, reuse blocked, revocation latency, quarantine outcomes, inaccessible steps, customer repetitions, and files stranded outside the intended case. Do not reward a platform for accepting a file that the assigned specialist cannot safely retrieve, or for displaying “uploaded” before validation finishes. Closure connects the invitation, retained evidence, permitted viewers, customer acknowledgement, and deletion or retention rule.`],extra:[source('NIST Secure Software Development Framework','https://csrc.nist.gov/pubs/sp/800/218/final','Secure-development practices relevant to token and workflow design.'),source('CISA File Upload Risks','https://www.cisa.gov/news-events/alerts/2017/12/08/mitigating-risk-file-uploads','Security context for accepting and validating uploaded files.'),source('FTC Data Security Guidance','https://www.ftc.gov/business-guidance/privacy-security/data-security','Business guidance for proportionate handling and protection of sensitive information.'),source('NIST Guide to Storage Encryption Technologies','https://csrc.nist.gov/pubs/sp/800/111/final','Protection context for stored customer evidence.')],related:['helpdesk-attachment-handling-research','outsourced-helpdesk-attachment-evidence-sufficiency-study','helpdesk-privacy-redaction-research']},
 {slug:'outsourced-helpdesk-watcher-notification-completeness-study',title:'Ticket Watcher Notification Completeness in Shared Support Queues',excerpt:'A delivery-chain study of whether subscribed owners receive the ticket events needed for decisions without treating a watcher list as proof of notice.',stats:[{value:'11',label:'notification chain events'},{value:'6',label:'failure injection classes'}],question:'Does a ticket watcher or subscriber receive, recognize, and accept the events required for an owned support decision across email, portal, chat, and mobile notification paths?',unit:'one material ticket event routed to one declared watcher from subscription state through generation, provider acceptance, delivery evidence, presentation, acknowledgement, and follow-up action',domain:[`Model the chain as subscription, eligibility, event trigger, template rendering, address or endpoint selection, provider acceptance, delivery, presentation, user acknowledgement, decision acceptance, and ticket update. A watcher badge establishes only configuration. A sent event establishes only generation. Even a delivered email cannot prove that the named owner understood or accepted the request. Define which events require an explicit in-ticket acceptance rather than passive notification.`, `Inject disabled notification preferences, digest delay, mailbox rejection, mobile quiet hours, removed project membership, address alias changes, thread muting, permission loss, template rendering failure, inaccessible action buttons, and a ticket transferred while the event is in flight. Test protected details for minimization: the notification may need to state impact and requested decision without exposing authentication evidence, customer files, or confidential comments outside the controlled ticket.`, `Measure expected versus generated notices, accepted versus rejected transport, acknowledged events, time to decision-owner acceptance, duplicate notifications, stale subscribers, unauthorized recipients, accessible fallback use, and customer checkpoints missed while the watcher remained silent. The corrective action may be an explicit task, backup owner, preference policy, routing integration, or smaller message. Adding more watchers can increase disclosure and diffuse responsibility rather than improve coverage.`],extra:[source('FEMA Effective Communication','https://www.fema.gov/emergency-managers/practitioners/integrated-public-alert-warning-system','Authoritative communication-system context for delivery and redundancy.'),source('NIST Incident Response Recommendations SP 800-61 Rev. 3','https://csrc.nist.gov/pubs/sp/800/61/r3/final','Incident communication and accountable response context.'),source('Federal Plain Language Guidelines','https://www.plainlanguage.gov/guidelines/','Guidance for actionable and understandable notification content.'),source('CISA Implementing Phishing-Resistant MFA','https://www.cisa.gov/resources-tools/resources/implementing-phishing-resistant-mfa','Context for protecting actions reached from notification channels.')],related:['helpdesk-customer-update-research','helpdesk-notification-delivery-research','helpdesk-escalation-timing-research']},
 {slug:'outsourced-helpdesk-routing-confidence-calibration-study',title:'Routing Confidence Calibration for Automated Help Desk Triage',excerpt:'A measurement protocol for deciding when an automated route is reliable enough to use, when it needs review, and when confidence is misleading.',stats:[{value:'8',label:'confidence calibration bands'},{value:'10',label:'consequence-aware challenge sets'}],question:'Do automated routing confidence values correspond to observed correctness and safe handling across ordinary, ambiguous, multilingual, protected, and out-of-scope help desk requests?',unit:'one frozen incoming request scored by the routing system and independently adjudicated against a declared taxonomy, authority boundary, and accepted destination',domain:[`Preserve model or rule version, input channel, minimized request text, language, product context, suggested category, suggested owner, confidence value, alternatives, threshold in force, human decision, adjudicated destination, protected-boundary flag, and customer consequence. Treat confidence as a system output, not a probability unless its design supports that interpretation. A value of 0.92 can still be poorly calibrated, and the cost of a wrong billing route differs from a wrong password-help route.`, `Create ten challenge sets: clear routine language, sparse wording, multiple intents, negation, quoted prior messages, multilingual or code-switched text, accessibility-related wording, suspected security signals, adversarial instructions, and requests outside the supported taxonomy. Freeze the set before tuning. Compare calibration curves and error types by consequence, language, channel, and product. Always inspect false-high-confidence cases because they are the mistakes most likely to bypass human review.`, `Define actions for confidence bands through observed evidence: automatic routing only for reversible low-consequence work, human confirmation for ambiguity, and mandatory protected routing when a risk signal appears regardless of the overall score. Measure correct destination, harmful miss, unnecessary escalation, time to accepted ownership, overrides, override agreement, and customer checkpoint accuracy. After a model or taxonomy change, rerun the frozen set plus new failures; historical confidence values should remain attributable to their original version.`],extra:[source('NIST AI Risk Management Framework','https://www.nist.gov/itl/ai-risk-management-framework','Risk governance and measurement context for automated triage.'),source('NIST AI RMF Playbook','https://airc.nist.gov/airmf-resources/playbook/','Operational actions for mapping, measuring, managing, and governing AI risk.'),source('NIST Adversarial Machine Learning Taxonomy','https://csrc.nist.gov/pubs/ai/100/2/e2025/final','Threat and failure taxonomy relevant to manipulated routing inputs.'),source('CISA Roadmap for Artificial Intelligence','https://www.cisa.gov/ai','Cybersecurity and infrastructure context for responsible AI adoption.')],related:['helpdesk-queue-routing-research','outsourced-helpdesk-ai-reply-control-study','helpdesk-quality-review-research']},
];

const researchBody = (s,index) => [
 `Research question: ${s.question} The analysis is designed for an outsourced help desk buyer deciding whether a control is sufficiently observable for live use. It does not claim that one platform, provider, workforce location, or tool is universally effective. The unit of analysis is ${s.unit}. Register study OHS-R${index + 1} with a frozen observation window, population definition, evidence inventory, reviewer roles, and decision owner before inspecting outcomes.`,
 `Population and selection for ${s.title}: include routine success, incomplete evidence, conflicting evidence, corrected records, unavailable systems, accessibility-relevant cases, protected decisions, rejected handoffs, and unresolved work. Declare inclusion and exclusion rules before review. Keep selected, available, reviewed, excluded, replaced, and unscorable counts separate. Never replace an inaccessible high-consequence record with a convenient success while keeping the original denominator.`,
 `Evidence model for ${s.title}: distinguish customer or third-party statements, system events, configuration, approved procedures, provider notes, delivery events, onsite observations, qualified findings, and owner decisions. Each artifact receives a stable reference, source owner, version or effective time, retrieval time, timezone, permitted use, and claim boundary. Later correction is appended rather than overwriting evidence that informed an earlier action.`,
 `Privacy and access for ${s.title}: use masked references and approved systems. Do not reproduce passwords, recovery codes, authentication tokens, full identity documents, customer files, payment data, private conversations, or restricted infrastructure details in the research sheet. Reviewers receive the minimum access required for frozen evidence. Conducting research never authorizes account change, customer contact outside approved channels, production testing, disclosure, or a commercial remedy.`,
 ...s.domain,
 `Adverse controls for ${s.title}: predict the expected stop state before introducing wrong-tenant identity, stale configuration, duplicate event, missing source, timezone boundary, failed owner acknowledgement, inaccessible customer path, unexpected sensitive data, system outage, and a source change after the first decision. A process passes only if it stops or routes as designed and leaves enough evidence to explain the result. Hidden facilitator intervention is recorded as a failure.`,
 `Independent review for ${s.title}: two reviewers receive the same frozen packet and independently record observed facts, missing evidence, classification, authority boundary, next owner, interim customer state, and closure decision. Preserve initial disagreements by field and reason before adjudication. Resolve them against sources and definitions, not seniority or the historical ticket outcome. Repeated disagreement is evidence that the rule or tool needs revision.`,
 `Analysis plan for ${s.title}: report counts with denominators, observation period, property or client mix, channels, languages where relevant, exclusions, missingness, correction rate, unresolved cases, and consequence class. Use distributions instead of only averages. Read representative records beside aggregates. Treat staffing, demand, configuration, product version, vendor coverage, policy changes, and unavailable evidence as alternative explanations rather than claiming causation from association.`,
 `Sampling and missingness protocol: include every predefined high-consequence case, then select ordinary records through a reproducible random or interval rule. Compare included and excluded cases by channel, client, age, consequence, ownership, and eventual disposition. Report concentrated missingness rather than smoothing it into an overall percentage. If the evidence needed to assess ${s.unit} is systematically absent in one queue, shift, language, or tool, treat that absence as a control finding and narrow any conclusion accordingly.`,
 `Replication and falsification for ${s.title}: give a second team the definitions, frozen evidence register, and analysis instructions without the first team’s conclusions. Ask it to recreate selection, classification, owner questions, calculations, exception treatment, and closure state. Then remove a relied-upon artifact and identify which conclusions no longer stand. Search deliberately for a competing explanation, wrong-account match, source version conflict, and successful outcome produced through an unauthorized path. Agreement reached through hidden context is not reproducibility.`,
 `Decision use and change control for ${s.title}: connect each finding to a mechanism, accountable owner, evidence, target date, acceptance test, rollback, and post-change observation. Separate observation, interpretation, recommendation, and authorized decision in the final brief. Management may expand, retain, narrow, pause, or retire the lane, but it records the affected customers and queues, residual uncertainty, safeguards, effective time, and next review trigger. Research ends with accountable use, not a detached score or provider ranking.`,
 `Authority boundary for ${s.title}: outsourced specialists may preserve reports, compare approved sources, perform documented routine actions, route decision packets, send approved customer checkpoints, and track acknowledgement. Client identity, security, privacy, legal, finance, product, and system owners retain consequential decisions. Urgency changes routing and communication frequency but does not create authority. A missing owner is a governance finding, not permission for the provider to decide.`,
 `Operational implication for ${s.title}: pilot the method in one declared support lane, publish its exclusions, and require owner acceptance of the stop conditions. Repair missing evidence, inaccessible routes, ambiguous fields, permission gaps, or unavailable decision capacity before expanding. Retest with different cases and ordinary user roles. Preserve rollback and customer-correction procedures so a measurement exercise cannot leave production or support records in an altered state.`,
 `Limitations for ${s.title}: remote records cannot establish every hidden system state, customer understanding, legal duty, technical cause, or downstream consequence. Logs may be incomplete or mutable, clocks may differ, and a declared observation window can miss delayed outcomes. Public sources guide control design; they do not inspect this provider, certify a workflow, set a universal threshold, or prove performance. Refresh after material client, platform, model, policy, staffing, or regulatory change.`,
 `Niche-specific conclusion: ${s.question} can be answered only within the declared sample and evidence boundary. The defensible output is a reproducible record of what was observed, which alternatives remain plausible, which owner accepted the decision, how the customer-facing state was reconciled, and what would cause the buyer to narrow, pause, repair, or expand the outsourced lane. A dashboard label or closed ticket cannot substitute for that chain.`,
];

const research = researchSpecs.map((s,i)=>({slug:s.slug,title:s.title,excerpt:s.excerpt,published:date,sourceDate:date,hero:`/research-thumbnails/${s.slug}.svg`,keyStats:s.stats,body:researchBody(s,i),sources:[...commonSources,...s.extra],related:s.related}));

fs.writeFileSync('app/oct12BlogArticles.ts',`export const oct12BlogArticles = ${JSON.stringify(blogs,null,2)} as const;\n`);
fs.writeFileSync('app/oct12Research.ts',`import type { ResearchPost } from './sep24Research';\nexport const oct12ResearchArticles: ResearchPost[] = ${JSON.stringify(research,null,2)};\n`);

const escapeXml = value => value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const wrap = (title, max=36) => {
  const words=title.split(' '), lines=[]; let line='';
  for(const word of words){const next=line?`${line} ${word}`:word;if(next.length>max&&line){lines.push(line);line=word}else line=next} if(line)lines.push(line); return lines;
};
const palettes=[['#041014','#0b2529','#2dd4bf','#f59e0b'],['#071b24','#123741','#54e0d1','#ffb13b'],['#0b1720','#17323b','#77e3d3','#f6a928']];
function svg(article,family,index){const [bg,panel,accent,gold]=palettes[index%palettes.length];const lines=wrap(article.title,family==='Blog'?29:25);const size=lines.length>3?36:lines.length===3?42:48;const tspans=lines.map((line,i)=>`<tspan x="82" dy="${i?size+14:0}">${escapeXml(line)}</tspan>`).join('');return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img" aria-labelledby="title desc"><title id="title">${escapeXml(article.title)}</title><desc id="desc">${family} thumbnail for Outsourced Helpdesk Services</desc><rect width="1200" height="630" fill="${bg}"/><rect x="34" y="34" width="1132" height="562" rx="28" fill="${panel}" stroke="${accent}" stroke-width="3"/><rect x="82" y="70" width="${family==='Blog'?278:330}" height="52" rx="13" fill="${accent}"/><text x="104" y="104" font-family="Arial,sans-serif" font-size="22" font-weight="700" fill="${bg}">${family==='Blog'?'HELP DESK PLAYBOOK':'HELP DESK RESEARCH'}</text><text x="82" y="202" font-family="Arial,sans-serif" font-size="${size}" font-weight="700" fill="#fff">${tspans}</text><path d="M82 492h640" stroke="${gold}" stroke-width="7" stroke-linecap="round"/><text x="82" y="550" font-family="Arial,sans-serif" font-size="25" font-weight="700" fill="${accent}">OUTSOURCED HELPDESK SERVICES</text><g transform="translate(918 180)"><rect width="180" height="230" rx="22" fill="${bg}" stroke="${accent}" stroke-width="3"/><circle cx="42" cy="48" r="16" fill="${gold}"/><path d="M76 40h70M76 58h48M34 104h112M34 143h112M34 182h76" stroke="${accent}" stroke-width="8" stroke-linecap="round"/></g></svg>\n`;}
for(const [family,items,dir] of [['Blog',blogs,'public/blog-thumbnails'],['Research',research,'public/research-thumbnails']]){fs.mkdirSync(dir,{recursive:true});items.forEach((article,i)=>fs.writeFileSync(`${dir}/${article.slug}.svg`,svg(article,family,i)));}

const articleRecords=[...blogs.map(a=>({section:'Blog',title:a.title,slug:a.slug,route:`/blog/${a.slug}`,sourcePath:'app/oct12BlogArticles.ts',thumbnailPath:`public${a.heroImage}`})),...research.map(a=>({section:'Research',title:a.title,slug:a.slug,route:`/research/${a.slug}`,sourcePath:'app/oct12Research.ts',thumbnailPath:`public${a.hero}`}))];
