fs.writeFileSync('publishing/2026-10-12/manifest.json',JSON.stringify({schemaVersion:1,site:'OutsourcedHelpdeskServices.com',canonicalDomain:'outsourcedhelpdeskservices.com',repository:'coolifystealthagents/outsourcedhelpdeskservices',branch:'main',baseSha:'cb997b93d1adcfce111d9e2bc1327a6bd54c0027',publicationDate:date,counts:{blog:12,research:5,total:17,thumbnails:17},registryPaths:['app/data.ts'],routePaths:['app/blog/[slug]/page.tsx','app/research/[slug]/page.tsx'],indexPaths:['app/blog/page.tsx','app/research/page.tsx'],sidebarPaths:['app/blog/[slug]/page.tsx','app/research/[slug]/page.tsx'],sitemapPaths:['app/sitemap.xml/route.ts'],articles:articleRecords},null,2)+'\n');
